/* Estrella del Balón · versión en inglés.
   El juego se escribe en español. Con el inglés activado, esta capa traduce lo que se ve en pantalla:
   - Frases exactas (EN_ADD) y palabras sueltas del juego (EN_WORDS).
   - Si un texto mezcla frases fijas con números o nombres, se traducen los trozos fijos que contiene.
   - Vigila los cambios de la página (MutationObserver), los textos de los lienzos (fillText) y el texto para compartir.
   Idioma: localStorage 'estrella_lang' ('es' o 'en'). Si no se ha elegido, inglés salvo que el navegador esté en español. */
var LANG=(function(){
 try{var l=localStorage.getItem('estrella_lang');if(l==='en'||l==='es')return l;}catch(e){}
 try{var n=String((typeof navigator!=='undefined'&&(navigator.language||(navigator.languages||[])[0]))||'es').toLowerCase();return n.indexOf('es')===0?'es':'en';}catch(e){return 'es';}
})();
function setLang(l){try{localStorage.setItem('estrella_lang',l);}catch(e){}if(typeof location!=='undefined')location.reload();}
/* selector de idioma (se muestra en el menú y en Carrera) */
function langSwitch(){
 var b=function(l,t){return '<button class="chip '+(LANG===l?'on':'')+'" data-a="lang" data-id="'+l+'" aria-pressed="'+(LANG===l)+'">'+t+'</button>';};
 return '<div class="mults notr" style="margin-top:8px">Idioma · Language: '+b('es','Español')+b('en','English')+'</div>';
}
var EN_X={},EN_W={};
function EN_ADD(a){a.forEach(function(s){var i=s.indexOf('|');if(i>0)EN_X[s.slice(0,i)]=s.slice(i+1);});}
function EN_WORDS(a){a.forEach(function(s){var i=s.indexOf('|');if(i>0)EN_W[s.slice(0,i)]=s.slice(i+1);});}
var enRe=null,enMap=null,enCache=null,EN_L=/[A-Za-zÀ-ÿ]/;
function enIsL(c){return !!c&&/[0-9A-Za-zÀ-ɏ]/.test(c);}
function enBuild(){
 enMap={};enCache=typeof Map!=='undefined'?new Map():null;
 /* trozos: frases con espacio o signos (no palabras sueltas, que podrían estar dentro de nombres) y palabras del juego */
 Object.keys(EN_X).forEach(function(k){if(k.length>=4&&/[\s.,:;·()¡!¿?«»→−+%º]/.test(k))enMap[k]=EN_X[k];});
 Object.keys(EN_W).forEach(function(k){enMap[k]=EN_W[k];});
 var keys=Object.keys(enMap).filter(function(k){return k.length>0;}).sort(function(a,b){return b.length-a.length;});
 enRe=!keys.length?/(?!)/g:new RegExp(keys.map(function(k){var e=k.replace(/[.*+?^${}()|[\]\\\/]/g,'\\$&');return enIsL(k.charAt(k.length-1))?e+'(?![0-9A-Za-z\\u00C0-\\u024F])':e;}).join('|'),'g');
}
var ORD=function(n){n=+n;var m=n%100;return n+(m>=11&&m<=13?'th':['th','st','nd','rd'][n%10]||'th');};
function enPost(r){
 return r.replace(/(\d+)\s?[ºª]/g,function(m,n){return ORD(n);}).replace(/(\d+(?:st|nd|rd|th)) a (\d+)/g,'$1 to $2').replace(/(\d+) de (\d+)/g,'$1 of $2').replace(/(\d),(\d)(?!\d)/g,'$1.$2').replace(/\bT(\d{1,2})\b/g,'S$1').replace(/\bJ(\d{1,2})\b/g,'MD$1').replace(/Fase de league/g,'League phase').replace(/Fase de grupos/g,'Group stage');
}
function enTx(s){
 if(LANG!=='en'||typeof s!=='string'||!s||!EN_L.test(s))return s;
 if(!enRe)enBuild();
 if(enCache){var c=enCache.get(s);if(c!==undefined)return c;}
 var t=s.trim(),r;
 /* textos en mayúsculas: se traducen como en minúsculas y se vuelven a poner en mayúsculas */
 if(EN_X[t]==null&&t.length>3&&t===t.toUpperCase()&&t!==t.toLowerCase()){
  var forms=[function(p){return p.charAt(0)+p.slice(1).toLowerCase();},function(p){return p.toLowerCase().replace(/(^|\s)\S/g,function(c){return c.toUpperCase();});}];
  for(var fi=0;fi<forms.length;fi++){var low=t.split(' · ').map(forms[fi]).join(' · '),tl=enTx(low);
   if(tl!==low){r=s.replace(t,tl.toUpperCase());if(enCache)enCache.set(s,r);return r;}}
 }
 if(EN_X[t]!=null)r=s.replace(t,EN_X[t]);
 else r=s.replace(enRe,function(m,off,str){
  /* una palabra que empieza a mitad de otra no se toca */
  if(enIsL(m.charAt(0))&&off>0&&enIsL(str.charAt(off-1)))return m;
  return enMap[m];});
 r=enPost(r);
 if(enCache){if(enCache.size>8000)enCache.clear();enCache.set(s,r);}
 return r;
}
var tr=enTx;
/* ---------- página ---------- */
var EN_ATTR=['aria-label','title','placeholder','alt'];
function enEl(el){
 if(!el||el.nodeType!==1)return;var tg=el.tagName;
 if(tg==='SCRIPT'||tg==='STYLE'||tg==='TEXTAREA')return;
 if(el.closest&&el.closest('.notr'))return;
 EN_ATTR.forEach(function(a){var v=el.getAttribute(a);if(v){var n=enTx(v);if(n!==v)el.setAttribute(a,n);}});
}
function enText(n){
 var p=n.parentNode;if(!p||p.nodeType!==1)return;var tg=p.tagName;
 if(tg==='SCRIPT'||tg==='STYLE'||tg==='TEXTAREA')return;
 if(p.closest&&p.closest('.notr'))return;
 var v=n.nodeValue;if(n.__en===v)return;var t=enTx(v);if(t!==v)n.nodeValue=t;n.__en=n.nodeValue;
}
function enNode(root){
 if(LANG!=='en'||!root)return;
 if(root.nodeType===3){enText(root);return;}
 if(root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==11)return;
 if(root.nodeType===1)enEl(root);
 if(root.querySelectorAll){var els=root.querySelectorAll('[aria-label],[title],[placeholder],[alt]');for(var i=0;i<els.length;i++)enEl(els[i]);}
 var w=document.createTreeWalker(root,4,null),x;while((x=w.nextNode()))enText(x);
}
function enInit(){
if(LANG==='en'&&typeof document!=='undefined'&&typeof MutationObserver!=='undefined'){
 try{document.documentElement.lang='en';}catch(e){}
 var enObs=new MutationObserver(function(recs){
  recs.forEach(function(r){
   if(r.type==='characterData'){enText(r.target);return;}
   if(r.type==='attributes'){enEl(r.target);return;}
   for(var i=0;i<r.addedNodes.length;i++)enNode(r.addedNodes[i]);});
  if(document.title&&document.title!==enTx(document.title))document.title=enTx(document.title);
 });
 var enStart=function(){enNode(document.body);enObs.observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:EN_ATTR});};
 if(document.body)enStart();else document.addEventListener('DOMContentLoaded',enStart);
 /* textos dibujados en lienzos (imagen para compartir, escenas) */
 try{var enFT=CanvasRenderingContext2D.prototype.fillText;CanvasRenderingContext2D.prototype.fillText=function(t,x,y,m){return m===undefined?enFT.call(this,enTx(String(t)),x,y):enFT.call(this,enTx(String(t)),x,y,m);};}catch(e){}
}
/* el texto para compartir */
if(typeof shareText==='function'){var enShare=shareText;shareText=function(){return enTx(enShare.apply(this,arguments));};}
}

